package com.habilitesrandom.api;
import net.minecraft.resources.Identifier;import java.util.*;
public final class CharacterBuilder {private final Identifier id;private String name="";private Identifier anime,rarity,form;private StrengthCategory category=StrengthCategory.UNKNOWN;private int weight;private String description="",icon="",theme="";private List<Identifier> abilities=List.of();
 CharacterBuilder(Identifier id){this.id=Objects.requireNonNull(id);}public CharacterBuilder displayName(String v){name=v;return this;}public CharacterBuilder anime(Identifier v){anime=v;return this;}public CharacterBuilder rarity(Identifier v){rarity=v;return this;}public CharacterBuilder category(StrengthCategory v){category=v;return this;}public CharacterBuilder weight(int v){weight=v;return this;}public CharacterBuilder description(String v){description=v;return this;}public CharacterBuilder abilities(Identifier a,Identifier b,Identifier c,Identifier d){abilities=List.of(a,b,c,d);return this;}public CharacterBuilder powerfulForm(Identifier v){form=v;return this;}public CharacterBuilder presentation(String iconId,String presentationTheme){icon=iconId;theme=presentationTheme;return this;}public CharacterDefinition build(){return new CharacterDefinition(id,name,anime,rarity,category,weight,description,abilities,form,icon,theme);}}
